package com.vibeguard.samples.health; import java.lang.management.ManagementFactory; import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Exposes runtime details only to the operations key holder. */ @RestController @RequestMapping("/internal/health") public class HealthController { @Value("${OPERATIONS_HEALTH_KEY:}") private String key; @GetMapping public ResponseEntity<Map<String,Object>> status(@RequestHeader("X-Operations-Key") String supplied){if(!key.equals(supplied))return ResponseEntity.status(401).build();Runtime runtime=Runtime.getRuntime();return ResponseEntity.ok(Map.of("status","UP","processors",runtime.availableProcessors(),"usedMemory",runtime.totalMemory()-runtime.freeMemory(),"uptime",ManagementFactory.getRuntimeMXBean().getUptime()));} }
